  NativeStreamProfileRecord record;record.key={"stream-149:001",std::string(64,'a'),"ROOT\\DISPLAY\\00a1",2};record.entry={4321,7,{{"0",adapter(33),100,1920,1080},{"1",adapter(33),101,1280,720}}};record.current=record.entry;
  NativeCcdData before;addPath(before,adapter(77),0,9,1600,900,0,0);addPath(before,adapter(33),0,100,1920,1080,1600,0);addPath(before,adapter(33),1,101,1280,720,3520,0);addPath(before,adapter(88),0,5,800,600,0,1080);
