  record.scope={2,std::string(64,'b'),1000,{{adapter(77),adapter(77),0,9,1,"console-source","console-target","console-monitor",true},{adapter(88),adapter(88),0,5,2,"foreign-source","foreign-target","foreign-monitor",true}}};
  record.console={{{"00112233-4455-6677-8899-aabbccddeeff"},"std"},{adapter(77),L"\\\\?\\PCI#VEN_1234&DEV_1111#0",L"PCI\\VEN_1234&DEV_1111\\3&0",L"PCI",{L"PCI\\VEN_1234&DEV_1111"},nativeConsoleDisplayClass,true,true},{adapter(77),adapter(77),0,9}};record.scope.foreign[0].sourcePath=record.scope.foreign[0].targetPath=utf8(record.console.device.interfacePath);return record;
