    std::thread resizeThread([&]{resize=journal.reserveResize(active,std::string(64,'c'),std::string(64,'d'));});std::thread stopThread([&]{stop=journal.requestStop(active);});resizeThread.join();stopThread.join();require(bool(resize)!=bool(stop),"Stop and resize both committed the same revision");
