  {std::ofstream file(path,std::ios::binary|std::ios::trunc);file<<"independent edit";}require(!journal.requestStop(active)&&readNativeJournalFile(path,trusted,nativeStreamProfileJournalLimit)==std::optional<std::string>("independent edit"),"File CAS overwrote independent bytes");++cases;++fileCases;
